// Inventory regression test (task V811-RT-A): asserts that the checked-in,
// dexdump-derived link requirements of the three audited extension APKs are a
// subset of this module's classpath. Evidence files live in
// src/test/resources/inventory/ and are regenerated by tools/inventory.py.
package com.yomira.core.extension.api

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonPrimitive
import java.util.concurrent.atomic.AtomicInteger

class InventoryLinkContractTest {

    private val extensions = listOf("mangafire", "weebcentral", "toonily")

    /**
     * External (non-eu.kanade) members the app's runtime classpath must
     * provide for extension DEXes to link. Mirrors the HOST-PROVIDED table in
     * .orchestrator/execution/runtime-link-inventory.md; anything not listed
     * here must resolve against this module's own dependency set.
     */
    private val hostProvided = listOf(
        // Real third-party artifacts the host must add (see inventory doc).
        "Lorg/jsoup/",
        "Luy/kohesive/injekt/",
        "Lcom/squareup/zstd/",
        "Lokhttp3/brotli/",
        "Lokhttp3/zstd/",
        "Lokhttp3/CompressionInterceptor",
        "Lkotlinx/serialization/json/okio/",
        // okhttp 5.x-only members on classes that also exist in the app's
        // okhttp 4.12.0; host must upgrade okhttp before enabling extensions.
        "Lokhttp3/Gzip;",
        "Lokhttp3/CacheControl\$Builder;->maxAge-LRDsOJo",
        // Version drift: members the extensions' toolchain (kotlinx-coroutines
        // 1.11.0, kotlin-stdlib 2.4.10 per extensions-source libs.versions.toml)
        // provides but the app's current 1.10.2 / 2.1.20 does not. Verified
        // present in the newer artifacts; host must upgrade or shim them.
        "Lkotlinx/coroutines/BuildersKt;->runBlockingK\$default",
        "Lkotlinx/coroutines/Job;->cancel\$default",
        "Lkotlin/time/Instant\$Companion;->parseOrNull",
    )

    private fun lines(resource: String): List<String> =
        javaClass.classLoader.getResourceAsStream("inventory/$resource")!!.bufferedReader()
            .readLines().filter { it.isNotBlank() }

    private fun isHostProvided(entry: String): Boolean = hostProvided.any { entry.startsWith(it) }

    @Test
    fun requiredEuKanadeTypesAreOnTheShimClasspath() {
        val union = mutableSetOf<String>()
        extensions.forEach { extension ->
            val required = lines("$extension.required.txt")
            val expected = apksJson().first { it.extension == extension }.required
            assertEquals("required count for $extension", expected, required.size)
            union += required.filter { it.startsWith("Leu/kanade/") }
        }
        assertTrue("No eu.kanade requirements found", union.isNotEmpty())
        val missing = union.filterNot { descriptor ->
            runCatching { DexDescriptors.loadClass(descriptor) }.isSuccess
        }
        assertEquals("Shim classpath is missing required types: $missing", emptyList<String>(), missing)
    }

    @Test
    fun referencedEuKanadeMembersResolveOnTheShimClasspath() {
        val union = mutableSetOf<String>()
        extensions.forEach { extension -> union += lines("$extension.members.txt") }
        val unresolved = union.filter { it.startsWith("Leu/kanade/") }.mapNotNull { entry ->
            val ref = DexDescriptors.parse(entry)
            if (DexDescriptors.resolve(ref) == null) entry else null
        }
        assertEquals("Shim classpath is missing referenced members: $unresolved", emptyList<String>(), unresolved)
    }

    @Test
    fun sourceEntryPointsOverriddenByExtensionsExistOnTheShimHierarchy() {
        // Methods the audited DEXes define on their HttpSource subclasses,
        // i.e. every member they expect to override. Single-letter names are
        // R8-mangled extension-private methods and are out of scope.
        val union = mutableSetOf<String>()
        extensions.forEach { extension -> union += lines("$extension.source-virtuals.txt") }
        val overridden = union
            .map { DexDescriptors.parse(it) }
            .filter { it.name.length >= 2 }
        assertTrue("No overridden ABI members found", overridden.isNotEmpty())

        val candidates = listOf(
            "Leu/kanade/tachiyomi/source/online/HttpSource;",
            "Leu/kanade/tachiyomi/source/CatalogueSource;",
            "Leu/kanade/tachiyomi/source/Source;",
            "Leu/kanade/tachiyomi/source/ConfigurableSource;",
            "Leu/kanade/tachiyomi/source/UnmeteredSource;",
        )
        val unresolved = overridden.mapNotNull { ref ->
            val resolved = candidates.any { owner ->
                DexDescriptors.resolveMethod(ref.copy(owner = owner)) != null
            }
            if (!resolved) "${ref.owner}->${ref.name}(${ref.params.joinToString("")})${ref.ret}" else null
        }
        assertEquals("Shim hierarchy is missing overridden members: $unresolved", emptyList<String>(), unresolved)
    }

    @Test
    fun externalMembersResolveUnlessDocumentedAsHostProvided() {
        val union = mutableSetOf<String>()
        extensions.forEach { extension -> union += lines("$extension.external-members.txt") }
        val skipped = AtomicInteger(0)
        val unresolved = union
            .filterNot { it.startsWith("Leu/kanade/") }
            .mapNotNull { entry ->
                if (isHostProvided(entry)) {
                    skipped.incrementAndGet()
                    null
                } else {
                    val resolved = runCatching {
                        val ref = DexDescriptors.parse(entry)
                        requireNotNull(DexDescriptors.resolve(ref)) { "not found" }
                    }.isSuccess
                    if (!resolved) entry else null
                }
            }
        assertTrue("Everything resolved; host-provided list is stale", skipped.get() > 0)
        assertEquals(
            "Unresolved externals missing from the host-provided table: $unresolved",
            emptyList<String>(),
            unresolved,
        )
    }

    @Test
    fun inventoryMetadataIsSelfConsistent() {
        val metadata = apksJson()
        assertEquals(3, metadata.size)
        extensions.forEach { extension ->
            val entry = metadata.first { it.extension == extension }
            assertTrue("sha256 for $extension", Regex("[0-9a-f]{64}").matches(entry.sha256))
            assertEquals("shim count for $extension", entry.shim, lines("$extension.shim.txt").size)
            assertEquals("member count for $extension", entry.members, lines("$extension.members.txt").size)
            assertTrue("required set for $extension", entry.required > 0)
            assertTrue("apk path recorded for $extension", entry.apk.isNotBlank())
        }
    }

    private data class ApkEntry(
        val extension: String,
        val apk: String,
        val sha256: String,
        val required: Int,
        val shim: Int,
        val members: Int,
    )

    private fun apksJson(): List<ApkEntry> {
        val stream = javaClass.classLoader.getResourceAsStream("inventory/apks.json")
            ?: error("apks.json missing")
        val array = kotlinx.serialization.json.Json.parseToJsonElement(stream.bufferedReader().readText())
            as? kotlinx.serialization.json.JsonArray
            ?: error("apks.json is not a JSON array")
        val entries = array.mapNotNull { element ->
            val obj = element as? kotlinx.serialization.json.JsonObject ?: return@mapNotNull null
            ApkEntry(
                extension = obj["extension"]!!.jsonPrimitive.content,
                apk = obj["apk"]!!.jsonPrimitive.content,
                sha256 = obj["sha256"]!!.jsonPrimitive.content,
                required = obj["required"]!!.jsonPrimitive.int,
                shim = obj["shim"]!!.jsonPrimitive.int,
                members = obj["members"]!!.jsonPrimitive.int,
            )
        }
        assertEquals(3, entries.size)
        return entries
    }
}
